CREATE TABLE IF NOT EXISTS agentEmailSettings (id INTEGER PRIMARY KEY AUTOINCREMENT,agentEmail TEXT NOT NULL UNIQUE,host TEXT NOT NULL,port INTEGER NOT NULL DEFAULT 587,secure INTEGER NOT NULL DEFAULT 0,user TEXT NOT NULL,password TEXT NOT NULL,fromEmail TEXT NOT NULL,fromName TEXT NOT NULL DEFAULT 'Affinity Financial',createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_email_settings_owner ON agentEmailSettings(agentEmail);
